import{_ as r,a as o,b as i}from"./chunks/ap-h743r1-size.B-ykZCJj.js";import{_ as l,C as s,o as n,c as d,j as e,a as h,E as u,al as p}from"./chunks/framework.7vp1BMOE.js";const A=JSON.parse('{"title":"AP-H743-R1 Flight Controller","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/x-mav_ap-h743r1.md","filePath":"ko/flight_controller/x-mav_ap-h743r1.md"}'),c={name:"ko/flight_controller/x-mav_ap-h743r1.md"};function m(b,t,g,f,P,M){const a=s("Badge");return n(),d("div",null,[t[0]||(t[0]=e("h1",{id:"ap-h743-r1-flight-controller",tabindex:"-1"},[h("AP-H743-R1 Flight Controller "),e("a",{class:"header-anchor",href:"#ap-h743-r1-flight-controller","aria-label":'Permalink to "AP-H743-R1 Flight Controller"'},"​")],-1)),u(a,{type:"tip",text:"PX4 v1.17"}),t[1]||(t[1]=p('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot.</p></div><p>The AP-H743-R1 is an advanced autopilot manufactured by X-MAV<sup>®</sup>.</p><p>The autopilot is recommended for commercial system integration, but is also suitable for academic research and any other applications. It brings you ultimate performance, stability, and reliability in every aspect.</p><p><img src="'+r+'" alt="AP-H743-R1"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>이 비행 컨트롤러는 <a href="./../flight_controller/autopilot_manufacturer_supported">제조업체에서 지원</a>합니다.</p></div><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li>FMU Processor: STM32H743VIT6 <ul><li>32 Bit Arm® Cortex®-M7, 480MHz, 2MB flash memory, 1MB RAM</li></ul></li><li>IO Processor: STM32F103 <ul><li>32 Bit Arm® Cortex®-M3, 72MHz, 20KB SRAM</li></ul></li><li>내장 센서 : <ul><li>Accel/Gyro: ICM-42688-P*2(Version1), BMI270*2(Version2)</li><li>Mag: QMC5883P</li><li>Barometer: SPL06</li></ul></li></ul><h3 id="인터페이스" tabindex="-1">인터페이스 <a class="header-anchor" href="#인터페이스" aria-label="Permalink to &quot;인터페이스&quot;">​</a></h3><ul><li>15x PWM Servo Outputs</li><li>1x Dedicated S.Bus Input</li><li>3x TELEM Ports</li><li>1x SERIAL4 Port</li><li>2x GPS Ports</li><li>1x USB Port (TYPE-C)</li><li>3x I2C Bus Ports</li><li>2x CAN Ports</li><li>2x Power Input Ports <ul><li>ADC Power Input</li><li>DroneCAN/UAVCAN Power Input</li></ul></li><li>2x Dedicated Debug Port <ul><li>FMU Debug</li><li>IO 디버그</li></ul></li></ul><h2 id="store" tabindex="-1">Purchase Channels <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Purchase Channels {#store}&quot;">​</a></h2><p>Order from <a href="https://www.x-mav.cn/" target="_blank" rel="noreferrer">X-MAV</a>.</p><h2 id="무선-조종" tabindex="-1">무선 조종 <a class="header-anchor" href="#무선-조종" aria-label="Permalink to &quot;무선 조종&quot;">​</a></h2><p>A Radio Control (RC) system is required if you want to manually control your vehicle (PX4 does not require a radio system for autonomous flight modes).</p><p>기체와 조종자가 통신하기 위하여 송신기와 수신기를 바인딩하여야 합니다. 송신기와 수신기의 매뉴얼을 참고하십시오.</p><p>SBUS receivers connect to the SBUS-IN input port. CRSF receiver must be wired to a spare port (UART) on the Flight Controller. Then you can bind the transmitter and receiver together.</p><h2 id="시리얼-포트-매핑" tabindex="-1">시리얼 포트 매핑 <a class="header-anchor" href="#시리얼-포트-매핑" aria-label="Permalink to &quot;시리얼 포트 매핑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>포트</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>GPS2</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM1</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>TELEM2</td></tr><tr><td>UART7</td><td>/dev/ttyS4</td><td>TELEM3</td></tr><tr><td>UART8</td><td>/dev/ttyS5</td><td>SERIAL4</td></tr></tbody></table><h2 id="pwm-output" tabindex="-1">PWM Output <a class="header-anchor" href="#pwm-output" aria-label="Permalink to &quot;PWM Output&quot;">​</a></h2><p>The AP-H743-R1 flight controller supports up to 15 PWM outputs. The first 8 outputs (labelled M1 to M8) are controlled by a dedicated STM32F103 IOMCU controller. The remaining 7 outputs (labelled A1 to A7) are the &quot;auxiliary&quot; outputs. These are directly attached to the STM32H743 FMU controller .</p><p>The 15 PWM outputs are:</p><p>M1 - M8 are connected to the IOMCU. A1 - A7 are connected to the FMU.</p><p>M1 - M8 support DShot and are in 3 groups:</p><ul><li>M1, M2 in group 1</li><li>M3, M4 in group 2</li><li>M5, M6, M7, M8 in group 3</li></ul><p>The 7 FMU PWM outputs are in 3 groups:</p><ul><li>A1 - A4 are in one group.</li><li>A5, A6 are in a 2nd group.</li><li>A7 is in a 3rd group.</li></ul><p>Channels within the same group need to use the same output rate. If any channel in a group uses DShot then all channels in the group need to use DShot.</p><h3 id="electrical-data" tabindex="-1">Electrical data <a class="header-anchor" href="#electrical-data" aria-label="Permalink to &quot;Electrical data&quot;">​</a></h3><ul><li>Voltage Ratings: <ul><li>Max input voltage: 5.4V</li><li>USB Power Input: 4.75~5.25V</li><li>Servo Rail Input: 0~9.9V</li></ul></li></ul><h2 id="battery-monitoring" tabindex="-1">Battery Monitoring <a class="header-anchor" href="#battery-monitoring" aria-label="Permalink to &quot;Battery Monitoring&quot;">​</a></h2><p>The board has connectors for 2 power monitors.</p><ul><li>POWER1 -- ADC</li><li>POWER2 -- DroneCAN</li></ul><p>The board is configure by default for a analog power monitor, and also has DroneCAN power monitor configured which is enabled.</p><h2 id="펌웨어-빌드" tabindex="-1">펌웨어 빌드 <a class="header-anchor" href="#펌웨어-빌드" aria-label="Permalink to &quot;펌웨어 빌드&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target, execute:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x-mav_ap-h743r1_default</span></span></code></pre></div><h2 id="pinouts-and-size" tabindex="-1">Pinouts and Size <a class="header-anchor" href="#pinouts-and-size" aria-label="Permalink to &quot;Pinouts and Size&quot;">​</a></h2><p><img src="'+o+'" alt="AP-H743-R1 pinouts"></p><p><img src="'+i+'" alt="AP-H743-R1"></p><h2 id="지원-플랫폼-및-기체" tabindex="-1">지원 플랫폼 및 기체 <a class="header-anchor" href="#지원-플랫폼-및-기체" aria-label="Permalink to &quot;지원 플랫폼 및 기체&quot;">​</a></h2><p>Any multirotor/airplane/rover or boat that can be controlled using normal RC servos or Futaba S-Bus servos. The complete set of supported configurations can be found in the <a href="./../airframes/airframe_reference">Airframe Reference</a>.</p><h2 id="debug_port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug_port" aria-label="Permalink to &quot;Debug Port {#debug_port}&quot;">​</a></h2><h3 id="swd" tabindex="-1">SWD <a class="header-anchor" href="#swd" aria-label="Permalink to &quot;SWD&quot;">​</a></h3><p>The <a href="./../debug/swd_debug">SWD interface</a> operate on the <strong>FMU-DEBUG</strong> port (<code>FMU-DEBUG</code>).</p><p>The debug port (<code>FMU-DEBUG</code>) uses a <a href="https://www.digikey.com/en/products/detail/jst-sales-america-inc/SM04B-GHS-TB/807788" target="_blank" rel="noreferrer">JST SM04B-GHS-TB</a> connector and has the following pinout:</p><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>5V+</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>FMU_SWDIO</td><td>+3.3V</td></tr><tr><td>3 (흑)</td><td>FMU_SWCLK</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table>',45))])}const x=l(c,[["render",m]]);export{A as __pageData,x as default};
